data.definition:
flowchart TD
    A["Start with the workload"] --> B{"Need OS-level control\nor custom software?"}
    B -->|Yes| VM["Virtual Machines"]
    B -->|No| C{"Is it event-driven or\nsporadic?"}
    C -->|Yes| FN["Azure Functions"]
    C -->|No| D{"Do you need containers?"}
    D -->|No| AS["App Service"]
    D -->|Yes| E{"Need the Kubernetes API\nor custom operators?"}
    E -->|Yes| AKS["AKS"]
    E -->|No| CA["Container Apps"]

data.code:
// Option A: App Service — always on, simplest to operate
resource plan 'Microsoft.Web/serverfarms@2023-01-01' = {
  name: 'plan-orders'
  location: location
  sku: { name: 'P0v3' }
  properties: { reserved: true } // Linux
}

resource app 'Microsoft.Web/sites@2023-01-01' = {
  name: 'app-orders-${uniqueSuffix}'
  location: location
  properties: { serverFarmId: plan.id }
}

// Option B: Container Apps — container image, scale to zero
resource env 'Microsoft.App/managedEnvironments@2023-05-01' = {
  name: 'env-orders'
  location: location
}

resource ca 'Microsoft.App/containerApps@2023-05-01' = {
  name: 'ca-orders'
  location: location
  properties: {
    managedEnvironmentId: env.id
    template: {
      containers: [
        { name: 'orders', image: 'ghcr.io/acme/orders:1.4.0' }
      ]
      scale: { minReplicas: 0, maxReplicas: 10 }
    }
  }
}
